   ratified vault. ***
   anchor      : HUB_DISTRIBUTION_CHANNEL   (kind: hub, origin: data_7.js.parent)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 2 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_DISTRIBUTION_CHANNEL_HK
   hashdiff    : SAT_CHANNEL_DEFINITION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_DISTRIBUTION_CHANNEL|' || (HUB_DISTRIBUTION_CHANNEL_BK__IMD_CODE))) as HUB_DISTRIBUTION_CHANNEL_HK
        , cast(null as varchar) as BROKERAGE_RATE
        , cast(null as varchar) as HEALTH_PRIME_RIDER_BROKERAGE_RATE
        , BDR_CODE as BUSINESS_DEVELOPMENT_MANAGER_REFERENCE
        , 'BJAZ_HDFC_SEC_FHPP' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hdfc_sec_fhpp') }}
    where (nullif(trim(IMD_CODE),'')) is not null
),

resolved as (
    select
        HUB_DISTRIBUTION_CHANNEL_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BROKERAGE_RATE end) as BROKERAGE_RATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then HEALTH_PRIME_RIDER_BROKERAGE_RATE end) as HEALTH_PRIME_RIDER_BROKERAGE_RATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BUSINESS_DEVELOPMENT_MANAGER_REFERENCE end) as BUSINESS_DEVELOPMENT_MANAGER_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_DISTRIBUTION_CHANNEL_HK
),

hashed as (
    select
        *,
        case when BROKERAGE_RATE is not null or HEALTH_PRIME_RIDER_BROKERAGE_RATE is not null or BUSINESS_DEVELOPMENT_MANAGER_REFERENCE is not null
                     then md5(upper(coalesce(cast(BROKERAGE_RATE as varchar), '') || '|' || coalesce(cast(HEALTH_PRIME_RIDER_BROKERAGE_RATE as varchar), '') || '|' || coalesce(cast(BUSINESS_DEVELOPMENT_MANAGER_REFERENCE as varchar), '')))
                end as SAT_CHANNEL_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_DISTRIBUTION_CHANNEL_HK is not null
  and SAT_CHANNEL_DEFINITION_HASHDIFF is not null
